import{_ as t,o,c as a,a2 as s}from"./chunks/framework.C9_66ieh.js";const g=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting.md","filePath":"troubleshooting.md","lastUpdated":1785285552000}'),r={name:"troubleshooting.md"};function n(i,e,l,d,c,h){return o(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>Common TrueDeck issues and fixes. Version target: <strong>0.3.x</strong>.</p><h2 id="cursor-ide-blocked-or-cursor-agent-missing" tabindex="-1">Cursor IDE blocked or Cursor Agent missing <a class="header-anchor" href="#cursor-ide-blocked-or-cursor-agent-missing" aria-label="Permalink to &quot;Cursor IDE blocked or Cursor Agent missing&quot;">​</a></h2><p><strong>Symptom:</strong> Error like <code>Blocked: Cursor IDE cannot be spawned</code> or Cursor shows unavailable in the palette.</p><p><strong>Cause:</strong> TrueDeck only runs <strong>cursor-agent CLI</strong>, never Cursor IDE (<code>Cursor.exe</code> / IDE <code>cursor.cmd</code>).</p><p><strong>Fix:</strong></p><ol><li>Install Cursor Agent CLI (Windows):</li></ol><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">irm https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cursor.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">install?win</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> iex</span></span></code></pre></div><ol start="2"><li>Confirm install under <code>%LOCALAPPDATA%\\cursor-agent\\</code> (versions with <code>node.exe</code> + <code>index.js</code>).</li><li>Restart TrueDeck so resolve cache refreshes (or wait ~5 minutes / reopen palette probe).</li><li>Do <strong>not</strong> point the agent command at <code>Program Files\\cursor\\…</code>.</li></ol><p>See <a href="./agents">Agents</a>.</p><h2 id="agent-cli-not-found" tabindex="-1">Agent CLI not found <a class="header-anchor" href="#agent-cli-not-found" aria-label="Permalink to &quot;Agent CLI not found&quot;">​</a></h2><p><strong>Symptom:</strong> <code>CLI not found (…); Install with: …</code></p><p><strong>Fix:</strong></p><ul><li>Install the vendor CLI and ensure it is on <code>PATH</code> for the same environment Electron inherits</li><li>On Windows, log out/in or restart TrueDeck after installing global npm tools</li><li>Check known paths (npm global under <code>%APPDATA%\\npm</code>, nvm4w, <code>~/.local/bin</code>)</li><li>Use the install one-liner from the error / <a href="./agents">Agents</a> table</li></ul><h2 id="agent-frame-missing-or-garbled" tabindex="-1">Agent frame missing or garbled <a class="header-anchor" href="#agent-frame-missing-or-garbled" aria-label="Permalink to &quot;Agent frame missing or garbled&quot;">​</a></h2><p><strong>Symptom:</strong> No TrueDeck header, or agent TUI fights the header.</p><p><strong>Fix:</strong></p><table tabindex="0"><thead><tr><th>Check</th><th>Action</th></tr></thead><tbody><tr><td>Setting</td><td>Settings → Terminal → <strong>Agent frame TUI</strong> on</td></tr><tr><td>Restart tab</td><td>Close and reopen the agent (<strong>Ctrl+T</strong>) - toggle applies to new tabs</td></tr><tr><td>Script present</td><td>Dev: <code>resources/agent-frame/truedeck-frame.mjs</code>; packaged: extraResources</td></tr><tr><td>node-pty</td><td>Frame needs <code>node-pty</code> via <code>NODE_PATH</code> / TrueDeck <code>node_modules</code></td></tr><tr><td>Shell panes</td><td>Shell only frames if <strong>Frame shell panes too</strong> is on</td></tr><tr><td>Conflict</td><td>Disable frame for agents that mishandle CSI offset</td></tr></tbody></table><p>See <a href="./agent-frame">Agent frame</a>.</p><h2 id="lag-many-panes" tabindex="-1">Lag / many panes <a class="header-anchor" href="#lag-many-panes" aria-label="Permalink to &quot;Lag / many panes&quot;">​</a></h2><p><strong>Symptom:</strong> UI or machine slows with many simultaneous agents.</p><p><strong>Fix:</strong></p><ul><li>Hard cap is <strong>16</strong> panes; soft warning near <strong>12</strong></li><li>Close unused agent tabs (each is a full CLI + model process)</li><li>Prefer side-by-side only when you actively compare agents</li><li>Build the Rust backend for lower I/O overhead (<a href="./RUST-BACKEND">RUST-BACKEND</a>, <a href="./FAST-PTY">FAST-PTY</a>) - does <strong>not</strong> reduce model latency</li></ul><h2 id="session-restore-tab-flood" tabindex="-1">Session restore tab flood <a class="header-anchor" href="#session-restore-tab-flood" aria-label="Permalink to &quot;Session restore tab flood&quot;">​</a></h2><p><strong>Symptom:</strong> On launch, many agent CLIs spawn at once.</p><p><strong>Cause:</strong> <code>reopenLastProject</code> + saved <code>session-layout.json</code> respawns up to <strong>16</strong> tabs.</p><p><strong>Fix:</strong></p><ul><li>Close tabs you do not need before quitting</li><li>Disable reopen last project in settings if you prefer a clean launch</li><li>Layout clamps to 16 and drops install-helper shells; still many real agents if you left them open</li><li>Delete or edit <code>session-layout.json</code> in the <a href="./configuration">data directory</a> as a last resort</li></ul><h2 id="term-colors-broken-agent-tui" tabindex="-1">TERM / colors / broken agent TUI <a class="header-anchor" href="#term-colors-broken-agent-tui" aria-label="Permalink to &quot;TERM / colors / broken agent TUI&quot;">​</a></h2><p><strong>Symptom:</strong> Agent UI lacks color, alt-screen, or mouse.</p><p><strong>Fix:</strong></p><ul><li>TrueDeck sets <code>TERM=xterm-256color</code>, <code>COLORTERM=truecolor</code>, <code>TERM_PROGRAM=TrueDeck</code> on spawn</li><li>Do not override <code>TERM</code> to <code>dumb</code> in the parent environment if you can avoid it</li><li>Resize the pane after spawn so xterm FitAddon / PTY rows match</li><li>Try with agent frame off if the CLI assumes full terminal ownership incorrectly</li></ul><h2 id="pty-backend-stuck-on-node-pty" tabindex="-1">PTY backend stuck on node-pty <a class="header-anchor" href="#pty-backend-stuck-on-node-pty" aria-label="Permalink to &quot;PTY backend stuck on node-pty&quot;">​</a></h2><p><strong>Symptom:</strong> Settings shows <code>node-pty (TS fallback)</code>.</p><p><strong>Fix:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:backend</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:pty</span></span></code></pre></div><p>Install <a href="https://rustup.rs" target="_blank" rel="noreferrer">rustup</a> + MSVC tools on Windows; free enough disk for the toolchain. Override path with <code>TRUEDECK_BACKEND_BIN</code> / <code>TRUEDECK_PTY_BIN</code> if needed.</p><h2 id="mcp-not-visible-in-cursor-claude-grok" tabindex="-1">MCP not visible in Cursor / Claude / Grok <a class="header-anchor" href="#mcp-not-visible-in-cursor-claude-grok" aria-label="Permalink to &quot;MCP not visible in Cursor / Claude / Grok&quot;">​</a></h2><p><strong>Fix:</strong></p><ol><li>Settings → MCP → ensure servers enabled</li><li>Run sync / <code>truedeck_apply_mcp</code> via hub tools</li><li>Confirm client config files were written (export JSON to verify map)</li><li>Restart the agent CLI after inject</li><li>Align <code>TRUEDECK_DATA_DIR</code> if you use a custom data dir</li></ol><p>See <a href="./mcp">MCP</a>.</p><h2 id="memory-palace-issues" tabindex="-1">Memory / palace issues <a class="header-anchor" href="#memory-palace-issues" aria-label="Permalink to &quot;Memory / palace issues&quot;">​</a></h2><p><strong>Fix:</strong></p><ul><li>TrueMemory files always work under <code>.memory/</code> offline</li><li>MemPalace: install native <code>mempalace</code> / <code>mempalace-mcp</code>, not Docker, for the default path</li><li>Set palace path in Settings / onboarding</li><li>Read <a href="./memory-providers">memory-providers.md</a></li></ul><p>Helpers:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">uv tool install mempalace</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\tools\\ensure</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mempalace.ps1</span></span></code></pre></div><h2 id="task-board-will-not-run" tabindex="-1">Task board will not run <a class="header-anchor" href="#task-board-will-not-run" aria-label="Permalink to &quot;Task board will not run&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Issue</th><th>Fix</th></tr></thead><tbody><tr><td>“Open a project first”</td><td><strong>Ctrl+O</strong></td></tr><tr><td>Agent missing</td><td>Install CLI; try Shell as smoke test</td></tr><tr><td>Task stuck running</td><td>Close the session tab; exit should move card toward review</td></tr><tr><td>No idea in frame</td><td>Dispatch sets <code>TRUEDECK_TASK_*</code> and <code>.truedeck/current-focus.md</code></td></tr></tbody></table><h2 id="electron-will-not-start-after-install" tabindex="-1">Electron will not start after install <a class="header-anchor" href="#electron-will-not-start-after-install" aria-label="Permalink to &quot;Electron will not start after install&quot;">​</a></h2><ul><li>Confirm Node 20+</li><li>Re-run <code>npm install</code> (rebuilds native modules for Electron)</li><li>Delete <code>node_modules</code> and reinstall if ABI mismatch after Electron upgrades</li><li>Check console for main-process errors when launching <code>npm start</code></li></ul><h2 id="shortcuts-not-working-in-terminal" tabindex="-1">Shortcuts not working in terminal <a class="header-anchor" href="#shortcuts-not-working-in-terminal" aria-label="Permalink to &quot;Shortcuts not working in terminal&quot;">​</a></h2><p>TrueDeck attaches a capture-phase keydown listener and filters xterm so app shortcuts work while focused. If a shortcut fails:</p><ul><li>Confirm it is in the <a href="./keyboard-shortcuts">shortcut table</a> (e.g. <strong>Ctrl+T</strong> = new agent, not next tab)</li><li>Avoid conflicting global OS hotkeys</li><li><strong>Ctrl+A</strong> is intentionally left to the terminal / agent</li></ul><h2 id="getting-more-detail" tabindex="-1">Getting more detail <a class="header-anchor" href="#getting-more-detail" aria-label="Permalink to &quot;Getting more detail&quot;">​</a></h2><ul><li>Main process logs appear in the terminal that launched <code>npm start</code></li><li>Look for tags: <code>[pty]</code>, <code>[backend]</code>, <code>[agent-frame]</code></li><li>Report issues with OS, TrueDeck version, agent id, and whether frame/Rust backend are enabled</li></ul>`,55)])])}const u=t(r,[["render",n]]);export{g as __pageData,u as default};
